const crypto = require('crypto');
const SECRET = 'demo-secret-placeholder';   // real keys come from a vault, never source code

const b64 = (s) => Buffer.from(s).toString('base64url');
const sign = (data) => crypto.createHmac('sha256', SECRET).update(data).digest('base64url');

// token = payload.signature ; payload is readable, but cannot be changed unnoticed
function issue(claims) {
  const payload = b64(JSON.stringify(claims));
  return payload + '.' + sign(payload);
}

// any server holding the secret can verify without a database lookup
function verify(token, now) {
  const [payload, sig] = token.split('.');
  const expected = sign(payload);
  if (!sig || sig.length !== expected.length ||
      !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) return 'rejected: bad signature';
  const claims = JSON.parse(Buffer.from(payload, 'base64url').toString());
  if (claims.exp < now) return 'rejected: expired';
  return 'accepted: user ' + claims.sub + ' role ' + claims.role;
}

const token = issue({ sub: 'u42', role: 'user', exp: 1000 });
console.log('token  :', token);
console.log('valid  :', verify(token, 500));
console.log('expired:', verify(token, 2000));

// attacker edits the payload to become admin, but cannot recompute the signature
const forged = b64(JSON.stringify({ sub: 'u42', role: 'admin', exp: 1000 })) + '.' + token.split('.')[1];
console.log('forged :', verify(forged, 500));
